#!/usr/bin/env python3
"""Writes resources/ai/foundry/models.yaml from the Azure model catalogue.

The interview offers models only from that file (`accepts: { catalogue: models.yaml }` on the question), never
from a model's memory: the catalogue moves every few weeks and a remembered model is a
retired one. This script turns one `az cognitiveservices model list --location <region>`
JSON per region into the list; the monthly workflow `.github/workflows/foundry-models.yml`
fetches the JSON and runs it.

Kept: models an `AIServices` account deploys, with a chat or embedding capability, not
`Legacy`, `Deprecating` or `Deprecated`, offered in at least one deployment type the
question set renders (Standard, DataZoneStandard, GlobalStandard) - and of each model
only its newest version. Newest first within each kind.

Usage:
    python3 update_foundry_models.py <dir with <region>.json files> [--out <models.yaml>]
                                     [--retrieved YYYY-MM-DD]

Needs PyYAML. Exit 0 written, 2 could not run.
"""

import argparse
import datetime
import glob
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
DEFAULT_OUT = os.path.join(HERE, '..', '..', 'plugins', 'infrastructure-as-skills-azure',
                           'resources', 'ai', 'foundry', 'models.yaml')
DEPLOYMENT_TYPES = ['Standard', 'DataZoneStandard', 'GlobalStandard']
RETIRING = {'Legacy', 'Deprecating', 'Deprecated'}
KINDS = ['chat', 'embedding']

HEADER = """\
# Generated by .github/scripts/update_foundry_models.py from the Azure model catalogue,
# refreshed monthly by .github/workflows/foundry-models.yml. Do not edit by hand.
#
# The interview offers models from this file only (`accepts: { catalogue: models.yaml }`
# on models.model_deployments): generally available ones first, newest first, never a model
# from memory. Each model appears once, in its newest version; Legacy and Deprecating ones
# are left out. A Preview `lifecycle` is named when offered; `retires`
# is the date the version stops answering. `deployment_types` maps each type to the
# regions that offer it - a model missing from the derived type is not deployed there.
"""


def kind_of(model):
    caps = model.get('capabilities') or {}
    name = model.get('name', '').lower()
    if 'rerank' in name:   # carries chatCompletion in the catalogue, but answers no chat
        return None
    if caps.get('embeddings') == 'true' or 'embed' in name:
        return 'embedding'
    if caps.get('chatCompletion') == 'true' or caps.get('responses') == 'true':
        return 'chat'
    return None


def released(model):
    """The version where it is a date, else the catalogue's creation date."""
    v = str(model.get('version', ''))
    m = re.fullmatch(r'(\d{4})-?(\d{2})-?(\d{2})', v)
    if m:
        return '-'.join(m.groups())
    created = ((model.get('systemData') or {}).get('createdAt') or '')[:10]
    return created or '0000-00-00'


def collect(files):
    models = {}
    regions = []
    for path in sorted(files):
        region = os.path.splitext(os.path.basename(path))[0]
        regions.append(region)
        with open(path, encoding='utf-8') as f:
            entries = json.load(f)
        for e in entries:
            if e.get('kind') != 'AIServices':
                continue
            m = e.get('model') or {}
            if m.get('lifecycleStatus') in RETIRING:
                continue
            kind = kind_of(m)
            if not kind:
                continue
            types = sorted({s.get('name') for s in m.get('skus') or []} & set(DEPLOYMENT_TYPES),
                           key=DEPLOYMENT_TYPES.index)
            if not types:
                continue
            key = (m.get('format'), m.get('name'), str(m.get('version')))
            entry = models.setdefault(key, {
                'name': m.get('name'),
                'version': str(m.get('version')),
                'format': m.get('format'),
                'kind': kind,
                'lifecycle': m.get('lifecycleStatus'),
                'released': released(m),
                'retires': ((m.get('deprecation') or {}).get('inference') or '')[:10] or None,
                'deployment_types': {},
            })
            for t in types:
                entry['deployment_types'].setdefault(t, set()).add(region)
    return regions, models


def newest_only(models):
    """One entry per model: the newest version, by release date, then by version."""
    def rank(e):
        v = e['version']
        return (e['released'], (1, int(v), '') if v.isdigit() else (0, 0, v))
    best = {}
    for e in models.values():
        key = (e['format'], e['name'])
        if key not in best or rank(e) > rank(best[key]):
            best[key] = e
    return {(e['format'], e['name'], e['version']): e for e in best.values()}


def ordered(models):
    def key(e):
        ga = 0 if e['lifecycle'] == 'GenerallyAvailable' else 1
        return (KINDS.index(e['kind']), ga, [-ord(c) for c in e['released']], e['name'], e['version'])
    out = []
    for e in sorted(models.values(), key=key):
        e = dict(e)
        e['deployment_types'] = {t: sorted(e['deployment_types'][t])
                                 for t in DEPLOYMENT_TYPES if t in e['deployment_types']}
        if e['retires'] is None:
            del e['retires']
        out.append(e)
    return out


def main():
    ap = argparse.ArgumentParser(description=__doc__.split('\n\n')[0])
    ap.add_argument('dir', help='directory holding one <region>.json per region')
    ap.add_argument('--out', default=DEFAULT_OUT)
    ap.add_argument('--retrieved', default=datetime.date.today().isoformat())
    args = ap.parse_args()
    try:
        import yaml
    except ImportError:
        print('no YAML parser available - pip install pyyaml', file=sys.stderr)
        return 2
    files = glob.glob(os.path.join(args.dir, '*.json'))
    if not files:
        print(f'no <region>.json in {args.dir}', file=sys.stderr)
        return 2
    regions, models = collect(files)
    models = newest_only(models)
    if not models:
        print('the catalogue held no chat or embedding model - refusing to write an empty list', file=sys.stderr)
        return 2
    doc = {'retrieved': args.retrieved, 'regions': regions, 'models': ordered(models)}
    with open(args.out, 'w', encoding='utf-8', newline='\n') as f:
        f.write(HEADER + '\n')
        yaml.safe_dump(doc, f, sort_keys=False, allow_unicode=True, width=200, default_flow_style=None)
    print(f'{len(doc["models"])} model version(s) from {len(regions)} region(s) -> {os.path.relpath(args.out)}')
    return 0


if __name__ == '__main__':
    sys.exit(main())
